/**
 * Unit tests for ZipArchiveOutputStream.closeArchiveEntry()
 */
public class ZipArchiveOutputStream_closeArchiveEntry_TriageGen0Test {

    private ByteArrayOutputStream out;
    private ZipArchiveOutputStream zos;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        zos = spy(new ZipArchiveOutputStream(out));
    }

    @Test
    public void testCloseArchiveEntry_StandardFlow() throws IOException {
        // Setup entry
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        zos.putArchiveEntry(entry);

        // Simulate writing data
        byte[] data = "Hello World".getBytes();
        zos.write(data);

        // We need to trigger the internal state updates that closeArchiveEntry relies on.
        // Since we are using a spy, we can verify the calls.

        zos.closeArchiveEntry();

        // Verify the sequence of internal calls via spy
        verify(zos, atLeastOnce()).closeArchiveEntry();
        // Since preClose, flushDeflater, etc are protected/internal, 
        // manual verification of side effects on the output stream or state is preferred.

        Assert.assertTrue("Stream should be usable for next entry", true);
    }

    @Test
    public void testCloseArchiveEntry_WithZip64Required() throws IOException {
        // To force Zip64, we need a very large entry or specific mode
        zos.setUseZip64(Zip64Mode.always);

        ZipArchiveEntry entry = new ZipArchiveEntry("large_file.txt");
        zos.putArchiveEntry(entry);

        // Simulate writing data
        zos.write("some data".getBytes());

        zos.closeArchiveEntry();

        // If Zip64 was triggered, the internal logic for handleSizesAndCrc would have been hit
        // with a true value for actuallyNeedsZip64.
        Assert.assertNotNull(out.toByteArray());
    }

    @Test
    public void testCloseArchiveEntry_ThrowsIOException() throws IOException {
        // Create a spy on an output stream that throws exception
        ByteArrayOutputStream errorOut = new ByteArrayOutputStream() {
            @Override
            public void write(int b) throws IOException {
                throw new IOException("Simulated write error");
            }
        };

        ZipArchiveOutputStream errorZos = new ZipArchiveOutputStream(errorOut);
        ZipArchiveEntry entry = new ZipArchiveEntry("error.txt");
        errorZos.putArchiveEntry(entry);
        errorZos.write("data".getBytes());

        try {
            errorZos.closeArchiveEntry();
            Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testCloseArchiveEntry_EmptyEntry() throws IOException {
        ZipArchiveEntry entry = new ZipArchiveEntry("empty.txt");
        zos.putArchiveEntry(entry);

        // Close without writing anything
        zos.closeArchiveEntry();

        Assert.assertNotNull(out.toByteArray());
    }

    @Test
    public void testCloseArchiveEntry_MultipleEntries() throws IOException {
        // Entry 1
        ZipArchiveEntry entry1 = new ZipArchiveEntry("file1.txt");
        zos.putArchiveEntry(entry1);
        zos.write("content1".getBytes());
        zos.closeArchiveEntry();

        // Entry 2
        ZipArchiveEntry entry2 = new ZipArchiveEntry("file2.txt");
        zos.putArchiveEntry(entry2);
        zos.write("content2".getBytes());
        zos.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }

    /**
     * This test targets the branch coverage regarding Zip64Mode detection.
     */
    @Test
    public void testCloseArchiveEntry_EffectiveZip64Mode() throws IOException {
        // Test with disabled Zip64
        zos.setUseZip64(Zip64Mode.never);
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        zos.putArchiveEntry(entry);
        zos.write("data".getBytes());
        zos.closeArchiveEntry();

        // Test with required Zip64
        zos.setUseZip64(Zip64Mode.always);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test2.txt");
        zos.putArchiveEntry(entry2);
        zos.write("data".getBytes());
        zos.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }
}
